#!/bin/sh
# prerm for the waylight .deb (as generated by dh_installsystemd): stop the
# service when the package is removed. Upgrades restart it in postinst.
set -e

if [ -d /run/systemd/system ] && [ "$1" = remove ]; then
	deb-systemd-invoke stop waylight-setup-info.timer waylight.service >/dev/null || true
fi

exit 0
